const e = await jira.getEpic();
const s = await jira.listStories();
return { epic: e.gone ? e : { summary: e.summary, desc: e.description.slice(0, 600), status: e.status.name }, stories: s.map(x => x.gone ? x : { id: x.id, sum: x.summary, st: x.status.name, pts: x.points, labels: x.labels, desc: x.description.slice(0, 250), comments: x.comments.map(c => c.body.slice(0, 150)) }) };

return await slices({ slices: [
 { name: "Drop the extras", defer: ["jira:SYN-117","jira:SYN-85"], keeps: ["Two-tap rebooking","Original fare kept on rebooking","Fix for alerts on departed sailings","SMS for passengers without the app"], loses: ["Waitlist for full replacement sailings","Web status page"] },
 { name: "App-first release", defer: ["jira:SYN-117","jira:SYN-85","jira:SYN-61"], keeps: ["Two-tap rebooking","Original fare kept on rebooking","Fix for alerts on departed sailings"], loses: ["Waitlist for full replacement sailings","Web status page","Any reach to passengers without the app"] }
], needs: [{ item: "jira:SYN-45", on: "jira:SYN-102", from: ["jira:SYN-45","jira:SYN-102"] }] });

